    struct { unsigned int LowPart; unsigned int HighPart; };
    ULONGLONG QuadPart;
} ULARGE_INTEGER;
ULONG EnlargedUnsignedDivide(ULARGE_INTEGER Dividend, ULONG Divisor, ULONG* Remainder)
{
    ULONG ulResult = (ULONG)(Dividend.QuadPart / Divisor);
